using System;using System.Linq;using System.Collections.Generic;using System.IO;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class RobotConnections {
  static Point3D Point(double[] p){return new Point3D(p[0],p[1],p[2]);}
  static Matrix3D Placement(RobotBuild build,RobotJoint j,BodyMate mate,double phase,bool animate){return build.Pose(j.Id+"_proc_"+mate.PartId,phase,animate);}
  public static List<string> Validate(RobotBuild build,double phase=0,bool animate=false){var errors=new List<string>();var current=build.Document.Joints.ToDictionary(j=>j.Id,j=>j.GeneratedBody!=null&&j.BodyGenerator!=null&&j.GeneratedBody.Fingerprint==ProceduralBodySpec.Fingerprint(build.Document,j,j.BodyGenerator));foreach(var j in build.Document.Joints){var result=j.GeneratedBody==null?null:j.GeneratedBody.Result;if(j.BodyGenerator==null||!j.BodyGenerator.Enabled||!j.BodyGenerator.Connected||result==null||result.Mates==null||!current[j.Id])continue;foreach(var mate in result.Mates)if(!mate.BoresVerified)errors.Add(j.Name+": отверстия стыка "+mate.Id+" не подтверждены.");var output=result.Mates.FirstOrDefault(m=>m.Id=="rotor_output");var input=result.Mates.FirstOrDefault(m=>m.Id=="link_input");if(output!=null&&input!=null)Compare(build,j,output,j,input,errors,phase,animate);foreach(var childPort in result.Mates.Where(m=>m.Id=="link_child")){var child=build.Document.Find(childPort.PeerJoint);if(child==null){errors.Add(j.Name+": ответное звено отсутствует.");continue;}var childResult=child.GeneratedBody==null?null:child.GeneratedBody.Result;if(childResult==null||childResult.Mates==null||!current[child.Id])continue;var stator=childResult.Mates.FirstOrDefault(m=>m.Id=="stator_mount");if(stator==null){errors.Add(child.Name+": нет ответного монтажного фланца.");continue;}Compare(build,j,childPort,child,stator,errors,phase,animate);}}return errors;}
  static void Compare(RobotBuild build,RobotJoint a,BodyMate x,RobotJoint b,BodyMate y,List<string> errors,double phase,bool animate){var left=Placement(build,a,x,phase,animate);var right=Placement(build,b,y,phase,animate);double distance=(left.Transform(Point(x.Origin))-right.Transform(Point(y.Origin))).Length;var nx=left.Transform(new Vector3D(x.Normal[0],x.Normal[1],x.Normal[2]));var ny=right.Transform(new Vector3D(y.Normal[0],y.Normal[1],y.Normal[2]));nx.Normalize();ny.Normalize();double miss=0;foreach(var p in x.BoltPoints){var point=left.Transform(Point(p));miss=Math.Max(miss,y.BoltPoints.Select(q=>(right.Transform(Point(q))-point).Length).Min());}if(distance>1e-5||Math.Abs(Vector3D.DotProduct(nx,ny))<1-1e-8||miss>1e-5)errors.Add(a.Name+" → "+b.Name+": стык разошёлся (фланцы "+Engine.F(distance)+" мм, отверстия "+Engine.F(miss)+" мм).");}
 }
 public sealed partial class RobotDesignerForm {
  internal static bool UpgradeReferenceSpacing(RobotDocument doc){var joints=doc.Ordered().ToArray();if(joints.Length!=6||doc.BodyEdits.Count!=0)return false;double[] lengths={180,220,170,110,100,85};var modes=new[]{RobotJointMode.Вращение_Z,RobotJointMode.Вращение_Y,RobotJointMode.Вращение_Y,RobotJointMode.Вращение_Z,RobotJointMode.Вращение_Y,RobotJointMode.Вращение_X};for(int i=0;i<6;i++){var j=joints[i];if(j.Mode!=modes[i]||j.ParentId!=(i==0?null:joints[i-1].Id)||Math.Abs(j.EndX-(i==5?85:0))>1e-6||Math.Abs(j.EndY)>1e-6||Math.Abs(j.EndZ-(i==5?0:lengths[i]))>1e-6||Math.Abs(j.OffsetX)>1e-6||Math.Abs(j.OffsetY)>1e-6||Math.Abs(j.OffsetZ-(i==0?130:0))>1e-6||Math.Abs(j.MotorFrame-41.9)>1e-6||Math.Abs(j.MotorLength-37.5)>1e-6||Math.Abs(j.GearboxDiameter-76)>1e-6||Math.Abs(j.GearboxLength-32)>1e-6)return false;}joints[3].EndZ=160;return true;}
  internal void ReconnectRobot(){bool upgraded=false;bool accepted=Mutate(()=>{upgraded=UpgradeReferenceSpacing(Document);foreach(var j in Document.Joints){j.BodyStyle=RobotBodyStyle.Закрытый_трубчатый;if(j.BodyGenerator==null)j.BodyGenerator=new ProceduralBodySettings();j.BodyGenerator.Connected=j.BodyGenerator.Enabled=j.BodyGenerator.AutoRegenerate=true;}});if(accepted&&upgraded)notes.AppendText("\r\nСтарый пример обновлён: J4 110 → 160 мм для посадок текущих NEMA 17. Изменение можно отменить.");}
 }
}
